# Each advanced entry is a complete machine-readable lesson plan, not falsely labeled as a written article.
def advanced(m,id,title,pre,summary,time,space,pitfall,exercise,path,level='advanced'):
 m['lessons'].append(dict(id=id,title=title,language='cpp',level=level,content_status='blueprint',prerequisites=pre.split(),estimated_minutes=90 if level=='core' else 150,objectives=[summary,'Derive the invariant or recurrence, justify correctness, and account for time and memory.','Implement from a blank file and compare with a small-input reference.'],study_outline=[{'step':'Model','task':summary},{'step':'Derive','task':'Work through a small example and state exactly what each stored value means.'},{'step':'Prove','task':'Identify the maintained invariant or induction hypothesis; justify each update.'},{'step':'Implement','task':'Write C++17 with explicit bounds, types, and ownership. Avoid relying on an unexplained template.'},{'step':'Stress-test','task':exercise},{'step':'Transfer','task':'Change one assumption and explain whether the same method still applies.'}],complexity={'time':time,'extra_space':space,'model':'State parameters explicitly; bounds assume ordinary word-sized arithmetic unless noted.'},common_pitfalls=[pitfall,'Confusing successful compilation or a memorized template with a correctness argument.'],practice={'type':'implementation-and-oracle','task':exercise,'steps':['Solve a tiny instance by hand.','Implement a straightforward oracle for small inputs.','Compare the optimized result against the oracle on random and boundary cases.','Return after a delay and reconstruct the invariant.']},mastery_gate={'explain_invariant':True,'independent_implementation':True,'randomized_cross_check':True,'unseen_transfer_problem':True},recall_cards=[dict(q=f'What is the central idea behind {title}?',a=summary),dict(q=f'What assumption or boundary can break {title}?',a=pitfall)],source_urls=['https://cp-algorithms.com/'+path]))
a=module('algebra','Algebra & number theory','cpp','Arithmetic structure, primes, modular methods, and combinatorial computation.')
rows=[
('gcd','Euclid, extended GCD, and linear Diophantine equations','cpp-stl-fast-io','Use remainders to preserve the gcd; track Bézout coefficients to solve ax + by = c.','O(log min(a,b)) word operations','O(1) iterative state','A solution exists only if gcd(a,b) divides c; normalize signs and handle zero inputs.','Compare gcd and Bézout identities across small signed pairs.','algebra/extended-euclid-algorithm.html'),
('binary-power','Binary exponentiation','cpp-stl-fast-io','Represent the exponent in binary and square the base while maintaining the accumulated power.','O(log e) multiplications','O(1)','Multiplication can overflow before reduction; exponent zero needs the identity element.','Compare with repeated multiplication for small exponents, including zero.','algebra/binary-exp.html'),
('sieve','Prime sieves and smallest prime factors','cpp-stl-fast-io','Mark composites from each prime’s square and optionally store the smallest prime factor.','O(n log log n) for Eratosthenes','O(n)','Starting at p*p can overflow an int before checking the bound.','Compare prime flags and factorizations with trial division up to 10000.','algebra/sieve-of-eratosthenes.html'),
('linear-sieve','Linear sieve','sieve','Assign each composite through its smallest prime factor exactly once.','O(n)','O(n)','The inner loop must stop at the first prime dividing the current value.','Compare smallest-prime-factor tables with Eratosthenes-based preprocessing.','algebra/prime-sieve-linear.html'),
('modular','Modular arithmetic and inverses','gcd binary-power','Normalize residues and distinguish addition, multiplication, and division via a modular inverse.','O(log m) for inverse via extended GCD','O(1)','An inverse exists only when gcd(a,m)=1; Fermat inversion requires prime modulus and nonzero residue.','Enumerate invertible residues for both prime and composite moduli.','algebra/module-inverse.html'),
('crt','Chinese remainder theorem','modular gcd','Combine congruences, checking compatibility when moduli are not coprime.','O(k log M) gcd/arithmetic steps; integer size matters','O(1) accumulation beyond inputs','Non-coprime residues must agree modulo the gcd, and the combined modulus may overflow.','Brute-force small systems, including inconsistent non-coprime cases.','algebra/chinese-remainder-theorem.html'),
('phi','Euler totient and multiplicative functions','sieve modular','Use prime factorization to count coprime residues and derive totient values.','O(sqrt n) trial factorization; O(N log log N) sieve variants','O(N) for a table','Euler’s exponent identity needs a base coprime to the modulus.','Count coprime residues directly for small n and compare.','algebra/phi-function.html'),
('primality','Miller–Rabin primality testing','binary-power modular','Test strong probable-prime witnesses using repeated squaring.','O(k log n) modular multiplications for k bases','O(1)','A fixed base set is deterministic only for its proven numeric range; modular products need safe arithmetic.','Compare against a sieve over a bounded range and include known pseudoprimes.','algebra/primality_tests.html'),
('factorization','Integer factorization and Pollard rho','primality gcd','Use randomized modular sequences and gcds to split composite factors recursively.','Randomized; no simple deterministic polynomial worst-case bound is claimed','O(log n) recursion depth in typical implementations','Handle even factors, primality checks, failed cycles, and overflow-safe modular multiplication.','Reconstruct every tested number from its prime factors.','algebra/factorization.html'),
('combinatorics','Binomial coefficients and factorial tables','modular','Choose Pascal DP or factorial/inverse-factorial methods according to n and the modulus.','O(N) table build plus O(log p) inverse; O(1) factorial-table query','O(N)','Factorial inversion under prime p fails once factorial contains p; composite moduli need different treatment.','Compare table formulas with Pascal’s triangle for small n.','combinatorics/binomial-coefficients.html'),
('inclusion-exclusion','Inclusion–exclusion','combinatorics','Correct overlapping counts by alternating over intersections of selected conditions.','O(2^k) subsets for k conditions, times intersection cost','O(k) recursion or subset state','An intersection size must count all imposed conditions together.','Count integers divisible by selected small primes and compare with a direct scan.','combinatorics/inclusion-exclusion.html'),
('matrix-power','Matrix exponentiation for recurrences','binary-power','Encode a fixed-size linear transition as matrix multiplication and exponentiate it.','O(d^3 log e) for naive d×d multiplication','O(d^2)','State order, multiplication order, and the identity matrix must match the recurrence.','Compare powered transitions against step-by-step recurrence evaluation.','algebra/binary-exp.html'),
('discrete-log','Discrete logarithms: baby-step giant-step','modular','Meet powers from two directions to solve a^x = b modulo m under stated assumptions.','O(sqrt m) expected hash operations for basic coprime variant','O(sqrt m)','The elementary variant assumes coprimality; non-coprime cases need reductions.','Compare minimal nonnegative exponents with brute force on small moduli.','algebra/discrete-log.html'),
('fft','FFT and polynomial convolution','cpp-stl-fast-io','Transform coefficients to point values, multiply pointwise, and invert the transform.','O(n log n) for padded transform length n','O(n)','Floating-point error and insufficient zero padding can corrupt integer coefficients.','Compare convolution against O(n²) multiplication on small random arrays.','algebra/fft.html'),
('ntt','Number-theoretic transforms','fft modular','Perform convolution using roots of unity in a suitable finite field.','O(n log n) for supported power-of-two length','O(n)','The modulus must support the transform length and the chosen primitive root.','Cross-check against quadratic modular convolution at every supported small length.','algebra/fft.html')]
