curriculum=dict(schema_version='2.0.0',title='Forge · C, C++ and the Algorithm Atlas',primary_standards={'c':'C17','cpp':'C++17'},authorship='Original explanations, study plans, exercises, and templates; topic coverage inspired by cp-algorithms.com. External articles retain their own licenses.',scope_note='This is a long-term map, not a claim that all advanced topics fit into 20 or 40 days. Complete lessons and blueprints are explicitly distinguished.',recommended_path=['cpp-foundations','cpp-stl','algebra','data-structures','dynamic-programming','graphs','strings','geometry'],optional_path=['c-foundations'],learning_policy={'prerequisite_gate':'Complete prerequisite lessons before recording completion. Blueprints are study plans and cannot be marked completed in the site.','review':'Add cards after a completed lesson; retrieve before reveal; rate honestly.','transfer':'Reconstruct code from memory, then solve an unseen variation.','deadline':'Prefer foundations and event-relevant patterns before advanced breadth.'},modules=modules)
ids={l['id'] for m in modules for l in m['lessons']}
assert len(ids)==sum(len(m['lessons']) for m in modules)
for m in modules:
 for l in m['lessons']:
  assert set(l['prerequisites'])<=ids,(l['id'],l['prerequisites'])
(ROOT/'content/curriculum.json').write_text(json.dumps(curriculum,ensure_ascii=False,indent=2)+'\n')
print(len(modules),'modules;',len(ids),'topics;',sum(l['content_status']=='complete' for m in modules for l in m['lessons']),'complete lessons')
